 38	  button {
 39	    font: inherit;
 40	    border: 0;
 41	    border-radius: 8px;
 42	    cursor: pointer;
 43	  }
 44	  .add { padding: 10px 16px; background: #0071e3; color: #fff; }
 45	  .add:hover { background: #0077ed; }
 46	  ul { list-style: none; margin: 16px 0 0; padding: 0; }
 47	  li {
 48	    display: flex;
 49	    align-items: center;
 50	    gap: 8px;
 51	    margin-top: 6px;
 52	    padding: 10px 8px 10px 12px;
 53	    border-radius: 8px;
 54	    background: #f2f2f4;
 55	  }
 56	  li:first-child { margin-top: 0; }
 57	  /* Priority colours: high red, med amber, low grey. */
 58	  li[data-priority="high"] { background: #fdecec; }
 59	  li[data-priority="med"] { background: #fff4de; }
 60	  li[data-priority="low"] { background: #f2f2f4; }
 61	  .priority { flex: none; padding: 2px 8px; border-radius: 999px; font-size: 12px; font-weight: 600; }
 62	  li[data-priority="high"] .priority { background: #f9d0d3; color: #b0000f; }
 63	  li[data-priority="med"] .priority { background: #fde2ad; color: #8a5300; }
 64	  li[data-priority="low"] .priority { background: #e3e3e8; color: #5e5e63; }
