 86	  <h1>Todos</h1>
 87	  <form id="todo-form" autocomplete="off">
 88	    <input type="text" data-testid="todo-input" id="todo-input" placeholder="What needs doing?" aria-label="New todo">
 89	    <input type="date" data-testid="todo-due" id="todo-due" aria-label="Due date (optional)">
 90	    <select data-testid="todo-priority" id="todo-priority" aria-label="Priority">
 91	      <option value="low">Low</option>
 92	      <option value="med" selected>Med</option>
 93	      <option value="high">High</option>
 94	    </select>
 95	    <button type="submit" class="add" data-testid="todo-add">Add</button>
 96	  </form>
 97	  <div class="filters" role="group" aria-label="Show">
 98	    <button type="button" class="filter" data-testid="filter-all" data-filter="all" aria-pressed="true">All</button>
 99	    <button type="button" class="filter" data-testid="filter-active" data-filter="active" aria-pressed="false">Active</button>
100	    <button type="button" class="filter" data-testid="filter-completed" data-filter="completed" aria-pressed="false">Completed</button>
101	  </div>
102	  <ul data-testid="todo-list" id="todo-list"></ul>
103	  <p class="empty" id="empty">Nothing here yet.</p>
104	</main>
105	<script>
106	(function () {
107	  var STORAGE_KEY = 'todos';
108	
109	  var form = document.getElementById('todo-form');
110	  var input = document.getElementById('todo-input');
111	  var dueInput = document.getElementById('todo-due');
112	  var priorityInput = document.getElementById('todo-priority');
113	  var list = document.getElementById('todo-list');
114	  var empty = document.getElementById('empty');
115	  var filterButtons = document.querySelectorAll('[data-filter]');
116	
117	  var filter = 'all';
118	
119	  function load() {
120	    try {
121	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
122	      return Array.isArray(data) ? data : [];
123	    } catch (e) {
124	      return [];
125	    }
126	  }
127	
128	  function save() {
129	    try {
130	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
131	    } catch (e) {
132	      // Storage unavailable or full; keep working in memory.
133	    }
134	  }
135	
136	  function newId() {
137	    if (window.crypto && typeof crypto.randomUUID === 'function') {
138	      return crypto.randomUUID();
139	    }
140	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
141	  }
142	
143	  var todos = load();
144	
145	  // Date rule (project decision): a due date is stored as a plain "YYYY-MM-DD"
146	  // string and means a LOCAL calendar date. Never pass it through Date parsing
147	  // or UTC (new Date("YYYY-MM-DD") is UTC midnight and shifts the day).
148	  // Overdue = due date strictly before today's local date; date-only, so a
149	  // todo due today is never overdue. Zero-padded strings compare correctly as text.
150	  var DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
151	
152	  function pad(n) {
153	    return (n < 10 ? '0' : '') + n;
154	  }
155	
156	  function todayLocal() {
157	    var now = new Date();
158	    return now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate());
159	  }
160	
161	  function validDue(value) {
162	    return typeof value === 'string' && DATE_RE.test(value) ? value : null;
163	  }
164	
165	  function isOverdue(todo) {
166	    var due = validDue(todo.due);
167	    return due !== null && due < todayLocal();
168	  }
169	
170	  // Priority rule: one of "low", "med", "high". Anything else (including todos
171	  // saved before priorities existed) is treated as "med".
172	  var PRIORITY_LABELS = { low: 'Low', med: 'Med', high: 'High' };
173	
174	  function validPriority(value) {
175	    return PRIORITY_LABELS.hasOwnProperty(value) ? value : 'med';
176	  }
177	
178	  function formatDue(due) {
179	    var parts = due.split('-');
180	    var year = Number(parts[0]);
181	    var date = new Date(year, Number(parts[1]) - 1, Number(parts[2])); // Local date.
182	    var options = { month: 'short', day: 'numeric' };
183	    if (year !== new Date().getFullYear()) options.year = 'numeric';
184	    return date.toLocaleDateString(undefined, options);
185	  }
186	
187	  // Ordering rule (project decision): completed todos always appear below all
188	  // active todos; within each group, todos stay in insertion order (oldest first).
189	  // `todos` is kept in insertion order, so a split preserves order in each group.
190	  function ordered() {
191	    var active = todos.filter(function (t) { return !t.completed; });
192	    var completed = todos.filter(function (t) { return t.completed; });
193	    return active.concat(completed);
194	  }
195	
196	  function visible() {
197	    return ordered().filter(function (t) {
198	      if (filter === 'active') return !t.completed;
199	      if (filter === 'completed') return !!t.completed;
200	      return true;
201	    });
202	  }
203	
204	  // Rows are kept by id and reused across renders, so a checkbox the user just
205	  // clicked stays the same element after the list is reordered or filtered.
206	  var rows = {};
207	
208	  function createRow(todo) {
209	    var li = document.createElement('li');
210	    li.setAttribute('data-testid', 'todo-item');
211	    li.setAttribute('data-id', todo.id);
212	
213	    var toggle = document.createElement('input');
214	    toggle.type = 'checkbox';
215	    toggle.className = 'toggle';
216	    toggle.setAttribute('data-testid', 'todo-toggle');
217	    toggle.addEventListener('change', function () {
218	      toggleTodo(todo.id);
219	    });
220	
221	    var content = document.createElement('div');
222	    content.className = 'content';
223	
224	    var text = document.createElement('span');
225	    text.className = 'text';
226	    text.setAttribute('data-testid', 'todo-text');
227	    text.textContent = todo.text;
228	
229	    var due = document.createElement('time');
230	    due.className = 'due';
231	    due.setAttribute('data-testid', 'todo-due-date');
232	
233	    content.appendChild(text);
234	    content.appendChild(due);
235	
236	    var priority = document.createElement('span');
237	    priority.className = 'priority';
238	
239	    var del = document.createElement('button');
240	    del.type = 'button';
241	    del.className = 'delete';
242	    del.setAttribute('data-testid', 'todo-delete');
243	    del.setAttribute('aria-label', 'Delete "' + todo.text + '"');
244	    del.textContent = 'Delete';
245	    del.addEventListener('click', function () {
246	      removeTodo(todo.id);
247	    });
248	
249	    li.appendChild(toggle);
250	    li.appendChild(content);
251	    li.appendChild(priority);
252	    li.appendChild(del);
253	    return li;
254	  }
255	
256	  function render() {
257	    var items = visible();
258	    var keep = {};
259	
260	    items.forEach(function (todo) {
261	      var li = rows[todo.id] || (rows[todo.id] = createRow(todo));
262	      var toggle = li.querySelector('.toggle');
263	      var dueLabel = li.querySelector('.due');
264	      var due = validDue(todo.due);
265	      var overdue = isOverdue(todo);
266	      var priority = validPriority(todo.priority);
267	      var priorityLabel = li.querySelector('.priority');
268	      li.setAttribute('data-priority', priority);
269	      priorityLabel.textContent = PRIORITY_LABELS[priority];
270	      priorityLabel.setAttribute('aria-label', PRIORITY_LABELS[priority] + ' priority');
271	      li.setAttribute('data-completed', todo.completed ? 'true' : 'false');
272	      li.setAttribute('data-overdue', overdue ? 'true' : 'false');
273	      dueLabel.hidden = due === null;
274	      if (due === null) {
275	        dueLabel.removeAttribute('datetime');
276	        dueLabel.textContent = '';
277	      } else {
278	        dueLabel.setAttribute('datetime', due);
279	        dueLabel.textContent = (overdue ? 'Overdue \u00b7 ' : 'Due ') + formatDue(due);
280	      }
281	      toggle.checked = !!todo.completed;
282	      toggle.setAttribute('aria-label', 'Mark "' + todo.text + '" as ' + (todo.completed ? 'not done' : 'done'));
283	      keep[todo.id] = true;
284	      list.appendChild(li); // Moves an existing row into place.
285	    });
286	
287	    Object.keys(rows).forEach(function (id) {
288	      if (keep[id]) return;
289	      if (rows[id].parentNode) rows[id].parentNode.removeChild(rows[id]);
290	      if (!todos.some(function (t) { return t.id === id; })) delete rows[id];
291	    });
292	
293	    filterButtons.forEach(function (button) {
294	      button.setAttribute('aria-pressed', button.getAttribute('data-filter') === filter ? 'true' : 'false');
295	    });
296	
297	    if (todos.length === 0) {
298	      empty.textContent = 'Nothing here yet.';
299	    } else if (filter === 'active') {
300	      empty.textContent = 'All done.';
301	    } else if (filter === 'completed') {
302	      empty.textContent = 'Nothing completed yet.';
303	    }
304	    empty.hidden = items.length > 0;
305	  }
306	
307	  function addTodo(text, due, priority) {
308	    todos.push({ id: newId(), text: text, completed: false, createdAt: Date.now(), due: due, priority: validPriority(priority) });
309	    save();
310	    render();
311	  }
312	
313	  function removeTodo(id) {
314	    todos = todos.filter(function (t) { return t.id !== id; });
315	    save();
316	    render();
317	  }
318	
319	  function toggleTodo(id) {
320	    todos.forEach(function (t) {
321	      if (t.id === id) t.completed = !t.completed;
322	    });
323	    save();
324	    render();
325	  }
326	
327	  function setFilter(value) {
328	    filter = value;
329	    render();
330	  }
331	
332	  filterButtons.forEach(function (button) {
333	    button.addEventListener('click', function () {
334	      setFilter(button.getAttribute('data-filter'));
335	    });
336	  });
337	
338	  form.addEventListener('submit', function (event) {
339	    event.preventDefault();
340	    var text = input.value.trim();
341	    if (!text) return;
342	    addTodo(text, validDue(dueInput.value), priorityInput.value);
343	    input.value = '';
344	    dueInput.value = '';
345	    priorityInput.value = 'med';
346	    input.focus();
347	  });
348	
349	  // "Today" moves at local midnight; re-render so overdue flags stay current.
350	  function scheduleMidnightRender() {
351	    var now = new Date();
352	    var next = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1);
353	    setTimeout(function () {
354	      render();
355	      scheduleMidnightRender();
356	    }, next - now + 1000);
357	  }
358	
359	  document.addEventListener('visibilitychange', function () {
360	    if (!document.hidden) render();
361	  });
362	
363	  render();
364	  scheduleMidnightRender();
365	})();
366	</script>
367	</body>
368	</html>

