// Ordering rule (project decision): completed todos always appear below all
// active todos. Within each group, todos are sorted by priority (high, med,
// low); within the same priority they stay in insertion order (oldest first).
// `todos` is kept in insertion order; the index tiebreak keeps the sort stable.
var PRIORITY_RANK = { high: 0, med: 1, low: 2 };

function byPriority(group) {
  return group
    .map(function (t, i) { return { todo: t, index: i }; })
    .sort(function (a, b) {
      return PRIORITY_RANK[validPriority(a.todo.priority)] - PRIORITY_RANK[validPriority(b.todo.priority)] ||
        a.index - b.index;
    })
    .map(function (entry) { return entry.todo; });
}

function ordered() {
  var active = todos.filter(function (t) { return !t.completed; });
  var completed = todos.filter(function (t) { return t.completed; });
  return byPriority(active).concat(byPriority(completed));
}

